-- Right click (Dao Si only): skill set of the client auto fight (PhongThanAutoFight.inl, Alt+A/S/D) by element:
-- Tho + Hoa + Bang (default), Hoa + Bang + Loi, all, one element, or skill by skill (also the 3 buffs, kept up
-- by the auto). Stored in task 2613 (0 = skills on the keys; else 2^30 + sum 2^(id - 3)), sent to the client with
-- SyncTaskValue (VNG s2c_synctaskvalue). Menus <= 7 rows; only learnt skills are listed.
-- Lua 4 / engine: no top-level dofile, one small statement per record (stack 120 slots).

PTLB_T_DS = 2613      -- Dao Si set: 0 = keys, else 2^30 + sum 2^(id - 3), ids 3..26
PTLB_T_DN = 2614      -- Di Nhan set: 0 = off, else 2^30 + sum 2^(id - 43), ids 43..51
PTLB_T_GDS = 2615     -- 1 = Lenh Bai Dao Si given (auto gift)
PTLB_T_GDN = 2616     -- 1 = Lenh Bai Di Nhan given (auto gift)
PTLB_ITEM_DS = 61480
PTLB_ITEM_DN = 61481
PTLB_FLAG = 1073741824

function PTLB_No()
end

function PTLB_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

function PTLB_Pow(k)
	local v = 1
	local i = 0
	while i < k do v = v * 2 i = i + 1 end
	return v
end

-- 1 when bit k of v is set (Lua 4: no bit operators)
function PTLB_Bit(v, k)
	local q = floor(v / PTLB_Pow(k))
	if q - floor(q / 2) * 2 == 1 then return 1 end
	return nil
end

function PTLB_Learnt(id)
	local l = HaveMagic(id)
	if l and l > 0 then return 1 end
	return nil
end

function PTLB_AddSk(t, id, el, kind, nm)
	local s = {}
	s.id = id
	s.el = el
	s.kind = kind
	s.nm = nm
	t.n = t.n + 1
	t[t.n] = s
end

