-- learnt skills of the table, in table order: { [1] = index in the table, ... }
function PTLBDS_LearntList()
	PTLB_Load()
	local r = {}
	local i = 1
	while i <= PTLB_DS.n do
		if PTLB_Learnt(PTLB_DS[i].id) then tinsert(r, i) end
		i = i + 1
	end
	return r
end

function PTLBDS_Page(pg)
	PTLB_Load()
	local l = PTLBDS_LearntList()
	local v = GetTask(PTLB_T_DS)
	if getn(l) == 0 then
		Say("<color=yellow>L\214nh B\181i \167\185o S\220<color>: b\185n ch\173a h\228c chi\170u n\181o trong danh s\184ch.", 1, "\167\227ng/PTLB_No")
		return
	end
	local last = floor((getn(l) + 3) / 4)
	if pg > last then pg = last end
	local o = {}
	local n = 0
	local i = (pg - 1) * 4 + 1
	while i <= pg * 4 and l[i] do
		local s = PTLB_DS[l[i]]
		local m = "[ ] "
		if PTLB_Has(PTLB_DS, v, s.id) then m = "[x] " end
		local d = PTLB_KIND[s.kind]
		if s.kind == 1 then d = PTLB_EL[s.el] end
		n = n + 1
		o[n] = m .. s.nm .. " - " .. d .. "/PTLBDS_T" .. l[i]
		i = i + 1
	end
	if pg < last then n = n + 1 o[n] = "Trang sau " .. (pg + 1) .. "/PTLBDS_P" .. (pg + 1) end
	n = n + 1 o[n] = "Quay l\185i/PTLBDS_Main"
	n = n + 1 o[n] = "\167\227ng/PTLB_No"
	PTLB_Say(PTLBDS_Title() .. " (" .. "trang " .. pg .. "/" .. last .. ")", o)
end

