-- toggle skill k of the table, then show the page that holds it
function PTLBDS_Toggle(k)
	PTLB_Load()
	local s = PTLB_DS[k]
	if not s or not PTLB_Learnt(s.id) then return end
	local v = GetTask(PTLB_T_DS)
	local on = nil
	if PTLB_Has(PTLB_DS, v, s.id) then v = PTLB_Without(PTLB_DS, v, s.id) else v = PTLB_With(PTLB_DS, v, s.id) on = 1 end
	-- nothing learnt left in the set: back to 0 (keys / off)
	local n, a = PTLB_Count(PTLB_DS, v)
	if n == 0 then v = 0 end
	PTLB_Apply(PTLB_T_DS, v)
	if on then Msg2Player("L\214nh B\181i \167\185o S\220: b\203t " .. s.nm) else Msg2Player("L\214nh B\181i \167\185o S\220: t\190t " .. s.nm) end
	local l = PTLBDS_LearntList()
	local pos = 1
	while l[pos] and l[pos] ~= k do pos = pos + 1 end
	PTLBDS_Page(floor((pos - 1) / 4) + 1)
end

